def f(inputs):
    factors = [0] * 10000
    for n in inputs:
        if n == 0:
            break
        i = 2
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                i += 1
        if n > 1:
            factors[n] += 1
    return sum(factors)
```

